-- Module: master — Master Data

CREATE SCHEMA IF NOT EXISTS master;
COMMENT ON SCHEMA master IS 'Master Data: Global, tenant-independent master tables (geography, currency) shared by every module.';

CREATE TABLE master.country (
    id uuid NOT NULL DEFAULT gen_random_uuid(),
    iso2 char(2),
    iso3 char(3),
    name varchar(120) NOT NULL,
    short_name varchar(60),
    phone_prefix varchar(8),
    sort_order integer,
    is_active boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now(),
    created_by uuid,
    updated_at timestamptz NOT NULL DEFAULT now(),
    updated_by uuid,
    deleted_at timestamptz,
    row_version integer NOT NULL DEFAULT 0,
    CONSTRAINT pk_country PRIMARY KEY (id),
    CONSTRAINT uq_country_iso2 UNIQUE (iso2)
);
COMMENT ON TABLE master.country IS 'Country master (ISO 3166-1).';
COMMENT ON COLUMN master.country.id IS 'Surrogate primary key (UUIDv7 generated by the application; database default is a v4 fallback).';
COMMENT ON COLUMN master.country.iso2 IS 'ISO 3166-1 alpha-2 code.';
COMMENT ON COLUMN master.country.iso3 IS 'ISO 3166-1 alpha-3 code.';
COMMENT ON COLUMN master.country.name IS 'Country name.';
COMMENT ON COLUMN master.country.short_name IS 'Short/common name.';
COMMENT ON COLUMN master.country.phone_prefix IS 'International dialling prefix, e.g. +91.';
COMMENT ON COLUMN master.country.sort_order IS 'Display order in pick-lists.';
COMMENT ON COLUMN master.country.is_active IS 'Whether the country is selectable.';
COMMENT ON COLUMN master.country.created_at IS 'Row creation time.';
COMMENT ON COLUMN master.country.created_by IS 'User account that created the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN master.country.updated_at IS 'Last update time.';
COMMENT ON COLUMN master.country.updated_by IS 'User account that last updated the row (audit reference to iam.user_account; not FK-constrained).';
COMMENT ON COLUMN master.country.deleted_at IS 'Soft-delete marker; NULL = live row.';
COMMENT ON COLUMN master.country.row_version IS 'Optimistic-locking version.';

