-- Intra-module foreign keys
ALTER TABLE master.state_province ADD CONSTRAINT fk_state_province_country_id FOREIGN KEY (country_id) REFERENCES master.country (id) ON DELETE RESTRICT;
CREATE INDEX ix_state_province_country_id ON master.state_province (country_id);
ALTER TABLE master.city ADD CONSTRAINT fk_city_country_id FOREIGN KEY (country_id) REFERENCES master.country (id) ON DELETE RESTRICT;
CREATE INDEX ix_city_country_id ON master.city (country_id);
ALTER TABLE master.city ADD CONSTRAINT fk_city_state_province_id FOREIGN KEY (state_province_id) REFERENCES master.state_province (id) ON DELETE RESTRICT;
CREATE INDEX ix_city_state_province_id ON master.city (state_province_id);

-- === P1-13: transactional outbox / inbox ===

CREATE TABLE master.outbox_event (
    id bigint GENERATED ALWAYS AS IDENTITY,
    tenant_id uuid,
    event_type varchar(120) NOT NULL,
    aggregate_type varchar(80) NOT NULL,
    aggregate_id uuid NOT NULL,
    payload text NOT NULL,
    occurred_at timestamptz NOT NULL DEFAULT now(),
    published_at timestamptz,
    CONSTRAINT pk_master_outbox_event PRIMARY KEY (id)
);
COMMENT ON TABLE master.outbox_event IS 'Transactional outbox of the master module: events written in the same transaction as the change, published to the bus by a relay, then pruned. Ordered by the identity column.';
COMMENT ON COLUMN master.outbox_event.id IS 'Monotonic sequence; publish order.';
COMMENT ON COLUMN master.outbox_event.tenant_id IS 'Owning tenant; NULL for platform-wide master-data events (geography, currency).';
COMMENT ON COLUMN master.outbox_event.event_type IS 'Event name (module.entity.verb).';
COMMENT ON COLUMN master.outbox_event.aggregate_type IS 'Entity kind the event is about.';
COMMENT ON COLUMN master.outbox_event.aggregate_id IS 'Entity id the event is about.';
COMMENT ON COLUMN master.outbox_event.payload IS 'Serialised event (opaque message envelope).';
COMMENT ON COLUMN master.outbox_event.occurred_at IS 'When the change committed.';
COMMENT ON COLUMN master.outbox_event.published_at IS 'When the relay published it (NULL = pending).';
CREATE INDEX ix_master_outbox_event_pending ON master.outbox_event (id) WHERE published_at IS NULL;
CREATE TABLE master.inbox_event (
    event_id uuid NOT NULL,
    tenant_id uuid NOT NULL,
    event_type varchar(120) NOT NULL,
    received_at timestamptz NOT NULL DEFAULT now(),
    processed_at timestamptz,
    processing_error text,
    CONSTRAINT pk_master_inbox_event PRIMARY KEY (event_id)
);
COMMENT ON TABLE master.inbox_event IS 'Inbox of the master module: ids of consumed events, kept so redeliveries are processed exactly once.';
COMMENT ON COLUMN master.inbox_event.event_id IS 'Global id of the consumed event.';
COMMENT ON COLUMN master.inbox_event.tenant_id IS 'Owning tenant (customer organisation). Row-level security key.';
COMMENT ON COLUMN master.inbox_event.event_type IS 'Event name.';
COMMENT ON COLUMN master.inbox_event.received_at IS 'First delivery time.';
COMMENT ON COLUMN master.inbox_event.processed_at IS 'When handling committed (NULL = in flight).';
COMMENT ON COLUMN master.inbox_event.processing_error IS 'Last handling error, if any.';

-- === P1-15: business uniqueness ignores soft-deleted rows ===

CREATE UNIQUE INDEX uq_state_province_1 ON master.state_province (country_id, name) WHERE deleted_at IS NULL;

-- === P0-03: row-level security (tenant isolation). The application role is not the table owner and sets app.tenant_id per transaction; a platform-admin role with BYPASSRLS serves cross-tenant operations ===

ALTER TABLE master.inbox_event ENABLE ROW LEVEL SECURITY;
ALTER TABLE master.inbox_event FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON master.inbox_event USING (tenant_id = current_setting('app.tenant_id', true)::uuid);
ALTER TABLE master.outbox_event ENABLE ROW LEVEL SECURITY;
ALTER TABLE master.outbox_event FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_isolation ON master.outbox_event USING (tenant_id IS NULL OR tenant_id = current_setting('app.tenant_id', true)::uuid);

-- === Review fixes: natural-key hygiene ===

CREATE UNIQUE INDEX uq_state_province_code ON master.state_province (country_id, code) WHERE code IS NOT NULL AND deleted_at IS NULL;
